## Submitted testbench
```systemverilog
module tb;

  // -----------------------------------------------------------------------
  // Parameters and clock generation
  // -----------------------------------------------------------------------
  localparam int    CLK_PERIOD = 8;               // 125 MHz
  localparam logic [15:0] PRESCALE = 16'd5;      // same as baseline tests

  // -----------------------------------------------------------------------
  // DUT‑level signals
  // -----------------------------------------------------------------------
  reg  clk        = 0;
  reg  rst        = 0;
  reg  rxd        = 1'b1;                       // UART receive line
  reg  m_axis_tready = 1'b0;                    // AXI‑Stream ready (driven)
  reg  [7:0] s_axis_tdata = 0;
  reg        s_axis_tvalid = 0;
  wire        m_axis_tdata;
  wire        m_axis_tvalid;
  wire        busy;          // from uart_rx (covered by cov_R25)
  wire        overrun_error;
  wire        frame_error;
  wire        tx_busy;
  wire        rx_busy;
  wire        txd;
  wire [15:0] prescale = PRESCALE;

  // -----------------------------------------------------------------------
  // Clock generation
  // -----------------------------------------------------------------------
  always #(CLK_PERIOD/2) clk = ~clk;

  // -----------------------------------------------------------------------
  // Reset sequence
  // -----------------------------------------------------------------------
  initial begin
    rst = 1'b0;
    #(CLK_PERIOD*2);
    rst = 1'b1;
    #(CLK_PERIOD*2);
    rst = 1'b0;
    #(CLK_PERIOD*2);
  end

  // -----------------------------------------------------------------------
  // UART byte transmitter (drives rxd)
  // -----------------------------------------------------------------------
  task automatic uart_send_byte(input byte unsigned b);
    int unsigned bit_clks = int'(prescale) * 8;
    // start bit
    rxd = 0;
    repeat (bit_clks) @(negedge clk);
    // 8 data bits, LSB first
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];
      repeat (bit_clks) @(negedge clk);
    end
    // stop bit
    rxd = 1;
    repeat (bit_clks) @(negedge clk);
    rxd = 1'b1;
  endtask

  // -----------------------------------------------------------------------
  // Simple waiting for a number of clock cycles
  // -----------------------------------------------------------------------
  task automatic wait_cycles(input int n);
    repeat (n) @(posedge clk);
  endtask

  // -----------------------------------------------------------------------
  // Flag and state machine to realise R25 coverage
  // -----------------------------------------------------------------------
  reg        pending_3c      = 0;
  reg [1:0]  accept_state    = 0;
  reg [15:0] wait_cnt        = 0;

  // Detect when a 0x3C word becomes ready (m_axis_tvalid high, m_axis_tready low)
  always @(posedge clk) begin
    if (!rst) begin
      pending_3c   <= 0;
      accept_state <= 0;
      wait_cnt     <= 0;
      m_axis_tready <= 1'b0;
    end else begin
      case (accept_state)
        0: begin
          if (m_axis_tvalid && !m_axis_tready && m_axis_tdata == 8'h3C) begin
            pending_3c   <= 1;
            accept_state <= 1;
            wait_cnt     <= 12; // wait a few cycles to let bit_cnt settle
          end
        end
        1: begin
          if (wait_cnt != 0) begin
            wait_cnt <= wait_cnt - 1;
          end else begin
            // Accept the pending word (assert m_axis_tready for one cycle)
            m_axis_tready <= 1'b1;
            @(posedge clk);
            m_axis_tready <= 1'b0;

            // -------------------------------------------------------------
            // Now transmit the second word 0xA5 and finish the simulation
            // -------------------------------------------------------------
            $display("Sending 0xA5 (expected to be accepted while busy)");
            uart_send_byte(8'hA5);

            // Give the design a little extra time for the coverage point
            // to evaluate before we terminate.
            wait_cycles(200);
            $finish;
          end
        end
      endcase
    end
  end

  // -----------------------------------------------------------------------
  // Instantiate the DUT (uart) – all ports are connected, unused ones tied off
  // -----------------------------------------------------------------------
  uart #(.DATA_WIDTH(8)) dut (
    .clk            (clk),
    .rst            (rst),

    // AXI‑Stream input side (unused for this Rx‑only coverage experiment)
    .s_axis_tdata   (s_axis_tdata),
    .s_axis_tvalid  (s_axis_tvalid),
    .s_axis_tready  (),            // tied to ground – not needed

    // AXI‑Stream output side (read side)
    .m_axis_tdata   (m_axis_tdata),
    .m_axis_tvalid  (m_axis_tvalid),
    .m_axis_tready  (m_axis_tready), // driven by testbench

    // UART interface
    .rxd            (rxd),
    .txd            (txd),

    // Status outputs
    .tx_busy        (tx_busy),
    .rx_busy        (rx_busy),
    .rx_overrun_error (overrun_error),
    .rx_frame_error   (frame_error),

    // Configuration
    .prescale       (prescale)
  );

endmodule
